        for bit,(dx,dy) in enumerate([(0,0),(0,1),(0,2),(1,0),(1,1),(1,2),(0,3),(1,3)]):
            if b & (1<<bit): px.add(i*2+dx)
    print(f"H={H}: cells={len(row)} px={sorted(px)}")
EOF
