{"command": "cd /tmp && cat <<'EOF' > grid.py
import subprocess,sys
def run(args, content):
    open('/tmp/x.txt','w').write(content)
    r = subprocess.run(['/workspace/executable']+args+['/tmp/x.txt'], capture_output=True)
    return r.stdout.decode()
def grid(s):
    rows=[]
    for l in s.rstrip('\n').split('\n'):
        cells=[ord(c)-0x2800 for c in l]
        w=len(cells)*2
        m=[]
        for y in range(4):
            m.append(''.join('#' if (cells[i] >> b) & 1 else '.' for i in range(len(cells)) for b in [] ) )
        # build columns
        g=[['.']*w for _ in range(4)]
        for i,b in enumerate(cells):
            for bit,(dx,dy) in enumerate([(0,0),(0,1),(0,2),(1,0),(1,1),(1,2),(0,3),(1,3)]):
                if b & (1<<bit):
                    g[dy][i*2+dx]='#'
        for y in range(4):
            rows.append(''.join(g[y]))
    return rows
def show(args, content, label=''):
    s = run(args, content)
    print(f"--- {label} {args}")
    for r in grid(s): print('   ', r)
content = '\n'.join('a'*n for n in range(1,9))+'\n'
for V in ['0.5','1','2']:
    show(['-V',V], content, f'V={V}')
EOF
python3 grid.py"}

