import subprocess
def run(args, content, exe='/workspace/executable'):
    open('/tmp/x.txt','w').write(content)
    r = subprocess.run([exe]+args+['/tmp/x.txt'], capture_output=True)
    return r.returncode, r.stdout.decode(), r.stderr.decode()
def rows(o):
    if o.endswith('\n'): o = o[:-1]
    return o.split('\n') if o else []
def hx(o):
    out=[]
    for l in rows(o):
        s=''
        for c in l:
            v=ord(c)-0x2800
            s += f'{v:02x}' if 0 <= v <= 0xff else '<'+repr(c)+'>'
        out.append(s)
    return out
def grid(o):
    g=[]
    for l in rows(o):
        cells=[ord(c)-0x2800 for c in l]
        m=[['.']*len(cells)*2 for _ in range(4)]
        for i,b in enumerate(cells):
            for bit,(dx,dy) in enumerate([(0,0),(0,1),(0,2),(1,0),(1,1),(1,2),(0,3),(1,3)]):
                if b & (1<<bit): m[dy][i*2+dx]='#'
        g += [''.join(r) for r in m]
    return g
EOF
