from harness import run, rows
def info(line):
    b = line.encode()
    print(f"  line={line!r} bytes={len(b)} chars={len(line)}")
    idx=0
    for ch in line:
        print(f"    U+{ord(ch):04X} byte_idx={idx} len={len(ch.encode())}")
        idx += len(ch.encode())
def bar(o):
    r = rows(o)
    cells=[ord(c)-0x2800 for c in r[0]] if r else []
    xs=set()
    for i,b2 in enumerate(cells):
        for bit,dx in [(0,0),(3,1),(6,0),(7,1)]:
