import sys; sys.path.insert(0,'/tmp')
from harness import run, hx, grid
def mk(idx, n=8, content=' '*(idx*4)+'aa'):
    lines=['']*n
    lines[idx]=content
    return '\n'.join(lines)+'\n'
for k in [2,3]:
    for V in ['1','0.5']:
        o = run(['-V',V], mk(k))[1]
        print(f'only L{k} V={V}: {hx(o)}')
        for g in grid(o): print('    ', g)
o = run(['-V','0.5'], '\n\n'+' '*(2*4)+'aa\n'+' '*(3*4)+'aa\n'+'\n'*4)[1]
print('L2+L3 V=0.5:', hx(o))
for g in grid(o): print('    ', g)
o = run(['-V','0.5'], 'aa\n'+' '*(1*4)+'aa\n'+' '*(2*4)+'aa\n'+' '*(3*4)+'aa\n'+'\n'*4)[1]
print('L0..L3 V=0.5:', hx(o))
for g in grid(o): print('    ', g)
