{"command": "mkdir -p /workspace/src && cd /workspace && cat > src/core.rs <<'RSEOF'
//! Core rendering logic for the code minimap.
//!
//! The minimap is drawn on a canvas of "pixels" which are then packed into
//! braille characters.  Every braille glyph covers a 2x4 block of pixels, so a
//! single glyph encodes eight pixels at once.

/// Characters that are considered whitespace when measuring a line.
///
/// The set mirrors the Unicode `White_Space` property which is what
/// `char::is_whitespace` tests for.
const WHITE_SPACE: &[(u32, u32)] = &[
    (0x0009, 0x000D),
    (0x0020, 0x0020),
    (0x0085, 0x0085),
    (0x00A0, 0x00A0),
    (0x1680, 0x1680),
    (0x2000, 0x200A),
    (0x2028, 0x2029),
    (0x202F, 0x202F),
    (0x205F, 0x205F),
    (0x3000, 0x3000),
];

fn is_white_space(ch: char) -> bool {
    let cp = ch as u32;
    WHITE_SPACE.iter().any(|&(lo, hi)| cp >= lo && cp <= hi)
}

/// Encoding used when the input is turned into text.
#[derive(Clone, Copy, PartialEq, Eq)]
pub enum Encoding {
    Utf8Lossy,
    Utf8,
}

/// Tunable knobs for the renderer.
#[derive(Clone, Copy)]
pub struct Options {
    /// Horizontal zoom factor, applied to the column positions.
    pub horizontal_scale: f64,
    /// Vertical zoom factor, applied to the line positions.
    pub vertical_scale: f64,
    /// Extra blank columns appended to every rendered row.
    pub padding: Option<usize>,
}

impl Default for Options {
    fn default() -> Self {
        Options {
            horizontal_scale: 1.0,
            vertical_scale: 1.0,
            padding: None,
        }
    }
}

/// Start and end (in bytes) of the ink drawn for a single line.
type Ink = (usize, usize);

/// Measure the ink of one line.
///
/// Leading and trailing whitespace does not produce any ink, everything in
/// between does.  Positions are byte offsets which is why multi byte
/// characters occupy more than one column.
fn measure(line: &str) -> Ink {
    let mut start = None;
    let mut end = 0usize;
    for (offset, ch) in line.char_indices() {
        if !is_white_space(ch) {
            if start.is_none() {
                start = Some(offset);
            }
            end = offset + 1;
        }
    }
    match start {
        Some(s) => (s, end),
        None => (0, 0),
    }
}

/// Render `content` into a minimap.
pub fn render(content: &str, options: &Options) -> String {
    let mut lines = content.split('\n');
    let collected: Vec<&str> = {
        let all: Vec<&str> = lines.by_ref().collect();
        match all.last() {
            Some(&"") => all[..all.len() - 1].to_vec(),
            _ => all,
        }
    };
    let inks: Vec<Ink> = collected.iter().map(|line| measure(line)).collect();

    let widest = inks.iter().map(|&(_, end)| end).max().unwrap_or(0);
    let canvas_width = ((std::cmp::max(1, widest) as f64) * options.horizontal_scale) as usize;

    let zoom = if options.vertical_scale > 1.0 {
        1.0
    } else {
        options.vertical_scale
    };
    let rows: Vec<usize> = collected
        .iter()
        .enumerate()
        .map(|(index, _)| (index as f64 * zoom) as usize)
        .collect();
    let deepest = rows.iter().cloned().max().unwrap_or(0);
    let canvas_height = (deepest + 4) / 4 * 4;

    // Longest run of ink per canvas row; neighbouring lines share a row and
    // their inks are joined together.
    let mut spans: Vec<Option<Ink>> = vec![None; canvas_height];
    for (ink, row) in inks.iter().zip(rows.iter()) {
        let (start, end) = *ink;
        if start >= end || *row >= canvas_height {
            continue;
        }
        match spans[*row] {
            None => spans[*row] = Some((start, end)),
            Some((s, e)) => {
                spans[*row] = Some((std::cmp::min(s, start), std::cmp::max(e, end)))
            }
        }
    }

    let mut canvas = vec![0u8; canvas_width * canvas_height];
    for (row, span) in spans.iter().enumerate() {
        if let Some((start, end)) = *span {
            let from = (start as f64 * options.horizontal_scale) as usize;
            let to = (end as f64 * options.horizontal_scale) as usize;
            for column in from..to {
                if column < canvas_width {
                    canvas[row * canvas_width + column] = 1;
                }
            }
        }
    }

    let glyphs = canvas_height / 4;
    let mut out = String::new();
    for glyph_row in 0..glyphs {
        let mut width = 0usize;
        for offset in 0..4 {
            let row = glyph_row * 4 + offset;
            let span = spans.get(row).copied().flatten();
            let end = match span {
                Some((_, end)) => end,
                None => 0,
            };
            let cells = ((std::cmp::max(1, end) as f64 * options.horizontal_scale) as usize + 1) / 2;
            width = std::cmp::max(width, cells);
        }
        if width == 0 {
            out.push('\n');
            continue;
        }
        let mut row = String::new();
        for cell in 0..width {
            let mut glyph: u8 = 0;
            for (bit, (dx, dy)) in DOT_ORDER.iter().enumerate() {
                let column = cell * 2 + dx;
                if column >= canvas_width {
                    continue;
                }
                let y = glyph_row * 4 + dy;
                if y >= canvas_height {
                    continue;
                }
                if canvas[y * canvas_width + column] != 0 {
                    glyph |= 1 << bit;
                }
            }
            row.push(char::from_u32(0x2800 + glyph as u32).unwrap());
        }
        // The padding width is a lower bound on the number of columns.
        let rendered = match options.padding {
            Some(width) => pad_to_width(&row, width),
            None => row,
        };
        out.push_str(&rendered);
        out.push('\n');
    }
    out
}

/// Screen order of the dots inside a braille glyph.
const DOT_ORDER: [(usize, usize); 8] = [
    (0, 0),
    (0, 1),
    (0, 2),
    (1, 0),
    (1, 1),
    (1, 2),
    (0, 3),
    (1, 3),
];

/// Left align `text` in a field of `width` columns.
fn pad_to_width(text: &str, width: usize) -> String {
    let text_length = text.chars().count();
    let out = format!("{:<width$}", text, width = width);
    let _ = text_length;
    out
}
RSEOF
echo written; wc -l src/core.rs"}

