//! Command line interface.
//!
//! The parser mirrors the behaviour users expect from a clap style interface:
//! flags may be given in any order, values may be attached with `=`, unknown
//! arguments produce a hint when a close match exists, and `--` stops option
//! processing altogether.

use std::ffi::OsString;
use std::path::Path;

use crate::core::{Encoding, Options};

/// The shells the completion file can be written for.
#[derive(Clone, Copy, PartialEq, Eq)]
pub enum Shell {
    Bash,
    Zsh,
    Fish,
    Elvish,
    Powershell,
}

impl Shell {
    /// Name of the shell as used on the command line.
    fn name(self) -> &'static str {
        match self {
            Shell::Bash => "bash",
            Shell::Zsh => "zsh",
            Shell::Fish => "fish",
            Shell::Elvish => "elvish",
            Shell::Powershell => "powershell",
        }
    }

    fn from_name(name: &str) -> Option<Shell> {
        match name {
            "bash" => Some(Shell::Bash),
            "zsh" => Some(Shell::Zsh),
            "fish" => Some(Shell::Fish),
            "elvish" => Some(Shell::Elvish),
            "powershell" => Some(Shell::Powershell),
            _ => None,
        }
    }

    fn all() -> [Shell; 5] {
