            Shell::Bash,
            Shell::Elvish,
            Shell::Fish,
            Shell::Powershell,
            Shell::Zsh,
        ]
    }

    fn names() -> Vec<&'static str> {
        Shell::all().iter().map(|shell| shell.name()).collect()
    }
}

/// What the program should do once the command line has been understood.
pub enum Outcome {
    /// Render a file, or standard input when no file was named.
    Render {
        file: Option<OsString>,
        options: Options,
        encoding: Encoding,
    },
    /// Print the completion script for a shell.
    Completion(Shell),
    /// Print the version banner.
    Version,
    /// Print a help screen.
    Help(Screen),
}

/// Which help screen should be shown.
pub enum Screen {
    Main,
    Completion,
}

/// A command line that could not be understood.
pub struct Failure {
    pub message: String,
}

impl Failure {
    fn new(message: String) -> Failure {
        Failure { message }
    }
}

/// A single option of the interface.
struct Spec {
    short: Option<char>,
    long: &'static str,
    /// Name as it appears in diagnostics.
    label: &'static str,
    takes_value: bool,
    choices: Option<&'static [&'static str]>,
}

const SPECS: [Spec; 6] = [
    Spec {
        short: Some('H'),
        long: "horizontal-scale",
