cd /workspace && cat > src/cli.rs <<'RSEOF'
//! Command line interface.
//!
//! The parser mirrors the behaviour users expect from a clap style interface:
//! flags may be given in any order, values may be attached with `=`, unknown
//! arguments produce a hint when a close match exists, and `--` stops option
//! processing altogether.

use std::ffi::OsString;
use std::path::Path;

use crate::core::{Encoding, Options};

/// The shells the completion file can be written for.
#[derive(Clone, Copy, PartialEq, Eq)]
pub enum Shell {
    Bash,
    Zsh,
    Fish,
    Elvish,
    Powershell,
}

impl Shell {
    /// Name of the shell as used on the command line.
    fn name(self) -> &'static str {
        match self {
            Shell::Bash => "bash",
            Shell::Zsh => "zsh",
            Shell::Fish => "fish",
            Shell::Elvish => "elvish",
            Shell::Powershell => "powershell",
        }
    }

    fn from_name(name: &str) -> Option<Shell> {
        match name {
            "bash" => Some(Shell::Bash),
            "zsh" => Some(Shell::Zsh),
            "fish" => Some(Shell::Fish),
            "elvish" => Some(Shell::Elvish),
            "powershell" => Some(Shell::Powershell),
            _ => None,
        }
    }

    fn all() -> [Shell; 5] {
        [
            Shell::Bash,
            Shell::Elvish,
            Shell::Fish,
            Shell::Powershell,
            Shell::Zsh,
        ]
    }

    fn names() -> Vec<&'static str> {
        Shell::all().iter().map(|shell| shell.name()).collect()
    }
}

/// What the program should do once the command line has been understood.
pub enum Outcome {
    /// Render a file, or standard input when no file was named.
    Render {
        file: Option<OsString>,
        options: Options,
        encoding: Encoding,
    },
    /// Print the completion script for a shell.
    Completion(Shell),
    /// Print the version banner.
    Version,
    /// Print a help screen.
    Help(Screen),
}

/// Which help screen should be shown.
pub enum Screen {
    Main,
    Completion,
}

/// A command line that could not be understood.
pub struct Failure {
    pub message: String,
}

impl Failure {
    fn new(message: String) -> Failure {
        Failure { message }
    }
}

/// A single option of the interface.
struct Spec {
    short: Option<char>,
    long: &'static str,
    /// Name as it appears in diagnostics.
    label: &'static str,
    takes_value: bool,
    choices: Option<&'static [&'static str]>,
}

const SPECS: [Spec; 6] = [
    Spec {
        short: Some('H'),
        long: "horizontal-scale",
        label: "--horizontal-scale <HSCALE>",
        takes_value: true,
        choices: None,
    },
    Spec {
        short: Some('V'),
        long: "vertical-scale",
        label: "--vertical-scale <VSCALE>",
        takes_value: true,
        choices: None,
    },
    Spec {
        short: None,
        long: "padding",
        label: "--padding <PADDING>",
        takes_value: true,
        choices: None,
    },
    Spec {
        short: None,
        long: "encoding",
        label: "--encoding <ENCODING>",
        takes_value: true,
        choices: Some(&["utf8-lossy", "utf8"]),
    },
    Spec {
        short: None,
        long: "version",
        label: "--version",
        takes_value: false,
        choices: None,
    },
    Spec {
        short: Some('h'),
        long: "help",
        label: "--help",
        takes_value: false,
        choices: None,
    },
];

/// The alternative form of the usage line used when an argument is guessed.
const GUESSED_USAGE: &str = "<FILE|--horizontal-scale <HSCALE>|--vertical-scale <VSCALE>|--padding <PADDING>|--encoding <ENCODING>|--version>";

/// What has been seen while scanning the command line.
#[derive(Default)]
struct Seen {
    horizontal: Option<String>,
    vertical: Option<String>,
    padding: Option<String>,
    encoding: Option<String>,
    version: bool,
    help: bool,
    file: Option<OsString>,
    /// Values in the order they were met, used for diagnostics.
    order: Vec<Entry>,
}

#[derive(Clone, Copy)]
enum Which {
    Horizontal,
    Vertical,
    Padding,
    Encoding,
    File,
}

enum Entry {
    Value(Which, String),
    Empty(Which),
}

impl Seen {
    /// Record that `which` was already given.
    fn duplicate(&self, which: Which, bin: &str) -> Option<Failure> {
        let label = match which {
            Which::Horizontal => "--horizontal-scale <HSCALE>",
            Which::Vertical => "--vertical-scale <VSCALE>",
            Which::Padding => "--padding <PADDING>",
            Which::Encoding => "--encoding <ENCODING>",
            Which::File => return None,
        };
        if self.taken(which) {
            return Some(Failure::new(format!(
                "error: the argument '{}' cannot be used multiple times\n\nUsage: {} [OPTIONS] [FILE] [COMMAND]\n\nFor more information, try '--help'.\n",
                label, bin
            )));
        }
        None
    }

    fn taken(&self, which: Which) -> bool {
        match which {
            Which::Horizontal => self.horizontal.is_some(),
            Which::Vertical => self.vertical.is_some(),
            Which::Padding => self.padding.is_some(),
            Which::Encoding => self.encoding.is_some(),
            Which::File => self.file.is_some(),
        }
    }

    fn store(&mut self, which: Which, value: String) {
        match which {
            Which::Horizontal => self.horizontal = Some(value),
            Which::Vertical => self.vertical = Some(value),
            Which::Padding => self.padding = Some(value),
            Which::Encoding => self.encoding = Some(value),
            Which::File => {}
        }
        self.order.push(Entry::Value(which, value));
    }

    fn store_empty(&mut self, which: Which) {
        self.order.push(Entry::Empty(which));
    }
}

/// Similarity of two strings, used to suggest close matches.
///
/// This is the Jaro-Winkler score, the same heuristic most shells use when
/// they offer a "did you mean" hint.
fn similarity(a: &str, b: &str) -> f64 {
    let first: Vec<char> = a.chars().collect();
    let second: Vec<char> = b.chars().collect();
    let (n, m) = (first.len(), second.len());
    if n == 0 || m == 0 {
        return 0.0;
    }
    let window = (std::cmp::max(n, m) / 2).saturating_sub(1);
    let mut marks_a = vec![false; n];
    let mut marks_b = vec![false; m];
    let mut hits = 0usize;
    for i in 0..n {
        let lo = i.saturating_sub(window);
        let hi = std::cmp::min(i + window + 1, m);
        for j in lo..hi {
            if !marks_b[j] && first[i] == second[j] {
                marks_a[i] = true;
                marks_b[j] = true;
                hits += 1;
                break;
            }
        }
    }
    if hits == 0 {
        return 0.0;
    }
    let mut transpositions = 0usize;
    let mut k = 0usize;
    for i in 0..n {
        if !marks_a[i] {
            continue;
        }
        while !marks_b[k] {
            k += 1;
        }
        if first[i] != second[k] {
            transpositions += 1;
        }
        k += 1;
    }
    let transpositions = transpositions / 2;
    let jaro = (hits as f64 / n as f64
        + hits as f64 / m as f64
        + (hits - transpositions) as f64 / hits as f64)
        / 3.0;
    let mut prefix = 0usize;
    for i in 0..std::cmp::min(std::cmp::min(n, m), 4) {
        if first[i] == second[i] {
            prefix += 1;
        } else {
            break;
        }
    }
    jaro + prefix as f64 * 0.1 * (1.0 - jaro)
}

/// Pick the closest of `choices` to `given`.
fn closest(given: &str, choices: &[&str]) -> Option<String> {
    let mut best: Option<(f64, &str)> = None;
    for choice in choices {
        let score = similarity(given, choice);
        if score > 0.7 && best.map(|(s, _)| score > s).unwrap_or(true) {
            best = Some((score, choice));
        }
    }
    best.map(|(_, name)| name.to_string())
}

/// Name of the binary as it will be shown in usage lines.
fn bin_name(argv0: Option<&OsString>) -> String {
    match argv0 {
        Some(arg) => Path::new(arg)
            .file_name()
            .map(|name| name.to_string_lossy().into_owned())
            .unwrap_or_else(|| "code-minimap".to_string()),
        None => "code-minimap".to_string(),
    }
}

fn help_text(bin: &str, screen: &Screen) -> String {
    match screen {
        Screen::Main => format!(
            "A high performance code minimap generator\n\nUsage: {} [OPTIONS] [FILE] [COMMAND]\n\nCommands:\n  completion\n          Generate shell completion file\n  help\n          Print this message or the help of the given subcommand(s)\n\nArguments:\n  [FILE]\n          File to read\n\nOptions:\n  -H, --horizontal-scale <HSCALE>\n          Specify horizontal scale factor [default: 1.0]\n  -V, --vertical-scale <VSCALE>\n          Specify vertical scale factor [default: 1.0]\n      --padding <PADDING>\n          Specify padding width\n      --encoding <ENCODING>\n          Specify input encoding [default: utf8-lossy] [possible values: utf8-lossy, utf8]\n      --version\n          Print version\n  -h, --help\n          Print help\n",
            bin
        ),
        Screen::Completion => format!(
            "Generate shell completion file\n\nUsage: {} completion <SHELL>\n\nArguments:\n  <SHELL>\n          Target shell name [possible values: bash, elvish, fish, powershell, zsh]\n\nOptions:\n  -h, --help\n          Print help\n",
            bin
        ),
    }
}

/// Scan the main command line.
pub fn parse(args: &[OsString]) -> Result<Outcome, Failure> {
    let bin = bin_name(args.first());
    let mut seen = Seen::default();
    let mut trailing = false;
    let mut order: Vec<Which> = Vec::new();
    let mut index = 1;
    let mut subcommand: Option<(String, Vec<OsString>)> = None;

    while index < args.len() {
        let raw = &args[index];
        let text = raw.to_string_lossy().into_owned();
        if !trailing && text == "--" {
            trailing = true;
            index += 1;
            continue;
        }
        if !trailing && text.starts_with("--") {
            let body = &text[2..];
            let (name, inline) = match body.find('=') {
                Some(pos) => (&body[..pos], Some(body[pos + 1..].to_string())),
                None => (body, None),
            };
            match name {
                "horizontal-scale" => {
                    if seen.taken(Which::Horizontal) {
                        return Err(duplicate(Which::Horizontal, &bin));
                    }
                    let value = take_value(args, &mut index, inline, Which::Horizontal, &bin, &mut seen)?;
                    seen.store(Which::Horizontal, value);
                    order.push(Which::Horizontal);
                    continue;
                }
                "vertical-scale" => {
                    if seen.taken(Which::Vertical) {
                        return Err(duplicate(Which::Vertical, &bin));
                    }
                    let value = take_value(args, &mut index, inline, Which::Vertical, &bin, &mut seen)?;
                    seen.store(Which::Vertical, value);
                    order.push(Which::Vertical);
                    continue;
                }
                "padding" => {
                    if seen.taken(Which::Padding) {
                        return Err(duplicate(Which::Padding, &bin));
                    }
                    let value = take_value(args, &mut index, inline, Which::Padding, &bin, &mut seen)?;
                    seen.store(Which::Padding, value);
                    order.push(Which::Padding);
                    continue;
                }
                "encoding" => {
                    if seen.taken(Which::Encoding) {
                        return Err(duplicate(Which::Encoding, &bin));
                    }
                    let value = take_value(args, &mut index, inline, Which::Encoding, &bin, &mut seen)?;
                    seen.store(Which::Encoding, value);
                    order.push(Which::Encoding);
                    continue;
                }
                "version" => {
                    if inline.is_some() {
                        return Err(unexpected(&text, &bin, &seen));
                    }
                    seen.version = true;
                    order.push(Which::File);
                    index += 1;
                    continue;
                }
                "help" => {
                    if inline.is_some() {
                        return Err(unexpected(&text, &bin, &seen));
                    }
                    seen.help = true;
                    order.push(Which::File);
                    index += 1;
                    continue;
                }
                _ => return Err(unexpected(&text, &bin, &seen)),
            }
        }
        if !trailing && text.starts_with('-') && text.len() > 1 {
            // Short flags may be bundled and may take an attached value.
            let chars: Vec<char> = text.chars().collect();
            let mut position = 1;
            while position < chars.len() {
                let flag = chars[position];
                match flag {
                    'H' | 'V' => {
                        let which = if flag == 'H' {
                            Which::Horizontal
                        } else {
                            Which::Vertical
                        };
                        if seen.taken(which) {
                            return Err(duplicate(which, &bin));
                        }
                        let rest: String = chars[position + 1..].iter().collect();
                        let attached = if rest.is_empty() {
                            None
                        } else if let Some(stripped) = rest.strip_prefix('=') {
                            Some(stripped.to_string())
                        } else {
                            Some(rest)
                        };
                        let value =
                            take_value(args, &mut index, attached, which, &bin, &mut seen)?;
                        seen.store(which, value);
                        order.push(which);
                        position = chars.len();
                        break;
                    }
                    'h' => {
                        seen.help = true;
                        order.push(Which::File);
                        position += 1;
                        continue;
                    }
                    _ => {
                        let name = format!("-{}", flag);
                        return Err(unexpected(&name, &bin, &seen));
                    }
                }
            }
            index += 1;
            continue;
        }
        // Positional argument or subcommand.
        if !trailing && (text == "completion" || text == "help") {
            let rest: Vec<OsString> = args[index + 1..].to_vec();
            subcommand = Some((text.clone(), rest));
            break;
        }
        if seen.taken(Which::File) {
            return Err(unexpected(&text, &bin, &seen));
        }
        seen.file = Some(raw.clone());
        if text.is_empty() {
            seen.store_empty(Which::File);
        }
        order.push(Which::File);
        index += 1;
    }

    if let Some((name, rest)) = subcommand {
        return run_subcommand(&name, &rest, &bin, &seen);
    }

    if seen.help {
        return Ok(Outcome::Help(Screen::Main));
    }
    if seen.version {
        return Ok(Outcome::Version);
    }

    // Required arguments and value conversion happen once the scan is done.
    validate(&mut seen, &order, &bin)?;
    Ok(build(&seen))
}

fn run_subcommand(
    name: &str,
    rest: &[OsString],
    bin: &str,
    seen: &Seen,
) -> Result<Outcome, Failure> {
    if name == "help" {
        return help_command(rest, bin);
    }
    let mut shell: Option<String> = None;
    let mut empty_shell = false;
    let mut help = false;
    let mut trailing = false;
    let mut index = 0;
    while index < rest.len() {
        let raw = &rest[index];
        let text = raw.to_string_lossy().into_owned();
        if !trailing && text == "--" {
            trailing = true;
            index += 1;
            continue;
        }
        if !trailing && text.starts_with("--") {
            let body = &text[2..];
            let (flag, inline) = match body.find('=') {
                Some(pos) => (&body[..pos], Some(body[pos + 1..].to_string())),
                None => (body, None),
            };
            match flag {
                "help" => {
                    if inline.is_some() {
                        return Err(unexpected(&text, bin, &Seen::default()));
                    }
                    help = true;
                    index += 1;
                    continue;
                }
                _ => return Err(unexpected(&text, bin, &Seen::default())),
            }
        }
        if !trailing && text.starts_with('-') && text.len() > 1 {
            let chars: Vec<char> = text.chars().collect();
            let mut position = 1;
            while position < chars.len() {
                match chars[position] {
                    'h' => {
                        help = true;
                        position += 1;
                    }
                    _ => {
                        let name = format!("-{}", chars[position]);
                        return Err(unexpected(&name, bin, &Seen::default()));
                    }
                }
            }
            index += 1;
            continue;
        }
        if shell.is_some() {
            return Err(unexpected(&text, bin, &Seen::default()));
        }
        if text.is_empty() {
            empty_shell = true;
        }
        shell = Some(text);
        index += 1;
    }
    if help {
        return Ok(Outcome::Help(Screen::Completion));
    }
    let value = match shell {
        Some(value) => value,
        None => {
            return Err(Failure::new(format!(
                "error: the following required arguments were not provided:\n  <SHELL>\n\nUsage: {} completion <SHELL>\n\nFor more information, try '--help'.\n",
                bin
            )))
        }
    };
    if empty_shell {
        return Err(Failure::new(
            "error: a value is required for '<SHELL>' but none was supplied\n\nFor more information, try '--help'.\n".to_string(),
        ));
    }
    match Shell::from_name(&value) {
        Some(shell) => Ok(Outcome::Completion(shell)),
        None => {
            let names = Shell::names();
            let list = names.join(", ");
            let hint = closest(&value, &names)
                .map(|name| format!("\n\n  tip: a similar value exists: '{}'", name))
                .unwrap_or_default();
            Err(Failure::new(format!(
                "error: invalid value '{}' for '<SHELL>'\n  [possible values: {}]{}\n\nFor more information, try '--help'.\n",
                value, list, hint
            )))
        }
    }
}

fn help_command(rest: &[OsString], bin: &str) -> Result<Outcome, Failure> {
    let mut names: Vec<String> = Vec::new();
    for raw in rest {
        names.push(raw.to_string_lossy().into_owned());
    }
    let mut screen = Screen::Main;
    let mut usage = format!("{} [OPTIONS] [FILE] [COMMAND]", bin);
    for name in &names {
        match (name.as_str(), &screen) {
            ("completion", Screen::Main) => {
                screen = Screen::Completion;
                usage = format!("{} completion <SHELL>", bin);
            }
            ("help", Screen::Main) => {
                screen = Screen::Help;
                usage = format!("{} help [COMMAND]...", bin);
            }
            _ => {
                return Err(Failure::new(format!(
                    "error: unrecognized subcommand '{}'\n\nUsage: {}\n\nFor more information, try '--help'.\n",
                    name, usage
                )))
            }
        }
    }
    Ok(Outcome::Help(screen))
}

/// Consume the value of an option, either inline or from the next argument.
fn take_value(
    args: &[OsString],
    index: &mut usize,
    inline: Option<String>,
    which: Which,
    bin: &str,
    seen: &mut Seen,
) -> Result<String, Failure> {
    match inline {
        Some(value) => {
            *index += 1;
            if value.is_empty() {
                seen.store_empty(which);
            }
            Ok(value)
        }
        None => {
            if *index + 1 >= args.len() {
                return Err(missing_value(which, bin));
            }
            let raw = &args[*index + 1];
            let text = raw.to_string_lossy().into_owned();
            if !text.is_empty() && text.starts_with('-') && text != "-" {
                // Values that look like flags are not consumed.
                return Err(missing_value(which, bin));
            }
            *index += 2;
            if text.is_empty() {
                seen.store_empty(which);
            }
            Ok(text)
        }
    }
}

fn missing_value(which: Which, _bin: &str) -> Failure {
    let label = match which {
        Which::Horizontal => "--horizontal-scale <HSCALE>",
        Which::Vertical => "--vertical-scale <VSCALE>",
        Which::Padding => "--padding <PADDING>",
        Which::Encoding => "--encoding <ENCODING>",
        Which::File => "[FILE]",
    };
    let extra = match which {
        Which::Encoding => "\n  [possible values: utf8-lossy, utf8]",
        _ => "",
    };
    Failure::new(format!(
        "error: a value is required for '{}' but none was supplied{}\n\nFor more information, try '--help'.\n",
        label, extra
    ))
}

fn duplicate(which: Which, bin: &str) -> Failure {
    let label = match which {
        Which::Horizontal => "--horizontal-scale <HSCALE>",
        Which::Vertical => "--vertical-scale <VSCALE>",
        Which::Padding => "--padding <PADDING>",
        Which::Encoding => "--encoding <ENCODING>",
        Which::File => "[FILE]",
    };
    Failure::new(format!(
        "error: the argument '{}' cannot be used multiple times\n\nUsage: {} [OPTIONS] [FILE] [COMMAND]\n\nFor more information, try '--help'.\n",
        label, bin
    ))
}

fn unexpected(text: &str, bin: &str, seen: &Seen) -> Failure {
    let stripped = text.trim_start_matches('-');
    let longs: Vec<&str> = SPECS.iter().map(|spec| spec.long).collect();
    let guess = closest(stripped, &longs);
    if let Some(name) = guess {
        let suggestion = format!("--{}", name);
        let usage = if name == "help" {
            if seen.taken(Which::File)
                || seen.taken(Which::Horizontal)
                || seen.taken(Which::Vertical)
                || seen.taken(Which::Padding)
                || seen.taken(Which::Encoding)
            {
                format!("{} --help {}", bin, GUESSED_USAGE)
            } else {
                format!("{} --help [FILE]", bin)
            }
        } else {
            format!("{} {}", bin, GUESSED_USAGE)
        };
        return Failure::new(format!(
            "error: unexpected argument '{}' found\n\n  tip: a similar argument exists: '{}'\n\nUsage: {}\n\nFor more information, try '--help'.\n",
            text, suggestion, usage
        ));
    }
    let tip = if text.starts_with('-') {
        format!(
            "\n\n  tip: to pass '{}' as a value, use '-- {}'",
            text, text
        )
    } else {
        String::new()
    };
    Failure::new(format!(
        "error: unexpected argument '{}' found{}\n\nUsage: {} [OPTIONS] [FILE] [COMMAND]\n\nFor more information, try '--help'.\n",
        text, tip, bin
    ))
}

/// Check the collected values and turn them into renderer options.
fn validate(seen: &mut Seen, order: &[Which], bin: &str) -> Result<(), Failure> {
    for entry in order {
        let which = match entry {
            Entry::Value(which, _) => *which,
            Entry::Empty(which) => *which,
        };
        match which {
            Which::File => {
                if let Entry::Empty(_) = entry {
                    return Err(Failure::new(
                        "error: a value is required for '[FILE]' but none was supplied\n\nFor more information, try '--help'.\n"
                            .to_string(),
                    ));
                }
            }
            Which::Horizontal => {
                if let Entry::Value(_, value) = entry {
                    let parsed: Result<f64, _> = value.parse();
                    if let Err(err) = parsed {
                        return Err(bad_value(value, "--horizontal-scale <HSCALE>", &err, bin));
                    }
                }
            }
            Which::Vertical => {
                if let Entry::Value(_, value) = entry {
                    let parsed: Result<f64, _> = value.parse();
                    if let Err(err) = parsed {
                        return Err(bad_value(value, "--vertical-scale <VSCALE>", &err, bin));
                    }
                }
            }
            Which::Padding => {
                if let Entry::Value(_, value) = entry {
                    let parsed: Result<usize, _> = value.parse();
                    if let Err(err) = parsed {
                        return Err(bad_value(value, "--padding <PADDING>", &err, bin));
                    }
                }
            }
            Which::Encoding => {
                if let Entry::Value(_, value) = entry {
                    if value.is_empty() {
                        return Err(missing_value(Which::Encoding, bin));
                    }
                    if crate::core::Encoding::from_name(value).is_none() {
                        let names = ["utf8-lossy", "utf8"];
                        let list = names.join(", ");
                        let hint = closest(value, &names)
                            .map(|name| format!("\n\n  tip: a similar value exists: '{}'", name))
                            .unwrap_or_default();
                        return Err(Failure::new(format!(
                            "error: invalid value '{}' for '--encoding <ENCODING>'\n  [possible values: {}]{}\n\nFor more information, try '--help'.\n",
                            value, list, hint
                        )));
                    }
                }
            }
        }
    }
    Ok(())
}

fn bad_value(value: &str, label: &str, err: &std::num::ParseFloatError, _bin: &str) -> Failure {
    Failure::new(format!(
        "error: invalid value '{}' for '{}': {}\n\nFor more information, try '--help'.\n",
        value, label, err
    ))
}

fn bad_int_value(value: &str, label: &str, err: &std::num::ParseIntError) -> Failure {
    Failure::new(format!(
        "error: invalid value '{}' for '{}': {}\n\nFor more information, try '--help'.\n",
        value, label, err
    ))
}

fn build(seen: &Seen) -> Outcome {
    let options = Options {
        horizontal_scale: seen
            .horizontal
            .as_ref()
            .and_then(|value| value.parse().ok())
            .unwrap_or(1.0),
        vertical_scale: seen
            .vertical
            .as_ref()
            .and_then(|value| value.parse().ok())
            .unwrap_or(1.0),
        padding: seen.padding.as_ref().and_then(|value| value.parse().ok()),
    };
    let encoding = seen
        .encoding
        .as_ref()
        .and_then(|value| crate::core::Encoding::from_name(value))
        .unwrap_or(Encoding::Utf8Lossy);
    Outcome::Render {
        file: seen.file.clone(),
        options,
        encoding,
    }
}
