//! Command line interface.
//!
//! The parser follows the conventions users expect from a clap style front
//! end: flags may appear in any order, values may be attached with `=`, short
//! flags may be bundled together, `--` stops option processing, and unknown
//! arguments produce a hint whenever a close match exists.

use std::ffi::OsString;
use std::path::Path;

use crate::core::{Encoding, Options};

/// The shells a completion script can be written for.
#[derive(Clone, Copy, PartialEq, Eq)]
pub enum Shell {
    Bash,
    Zsh,
    Fish,
    Elvish,
    Powershell,
}

impl Shell {
    /// Name of the shell as spelled on the command line.
    pub fn name(self) -> &'static str {
        match self {
            Shell::Bash => "bash",
            Shell::Zsh => "zsh",
            Shell::Fish => "fish",
            Shell::Elvish => "elvish",
            Shell::Powershell => "powershell",
        }
    }

    fn from_name(name: &str) -> Option<Shell> {
        match name {
            "bash" => Some(Shell::Bash),
            "zsh" => Some(Shell::Zsh),
            "fish" => Some(Shell::Fish),
            "elvish" => Some(Shell::Elvish),
            "powershell" => Some(Shell::Powershell),
            _ => None,
        }
    }

    /// Names in the order they are advertised.
    fn names() -> Vec<&'static str> {
        vec![
            Shell::Bash.name(),
            Shell::Elvish.name(),
            Shell::Fish.name(),
            Shell::Powershell.name(),
            Shell::Zsh.name(),
        ]
    }
}

/// Which help screen should be printed.
pub enum Screen {
    Main,
    Completion,
    Help,
}

/// What the program should do once the command line is understood.
pub enum Outcome {
    /// Render a file, or standard input when no file was named.
    Render {
        file: Option<OsString>,
        options: Options,
        encoding: Encoding,
    },
    /// Print the completion script of a shell.
    Completion(Shell),
    /// Print the version banner.
    Version,
    /// Print a help screen.
    Help(Screen),
}

/// A command line that could not be understood.
pub struct Failure {
    pub message: String,
}

impl Failure {
    fn new(message: String) -> Failure {
        Failure { message }
    }
}

/// The option that a diagnostic talks about.
#[derive(Clone, Copy, PartialEq, Eq)]
enum Which {
    Horizontal,
    Vertical,
    Padding,
    Encoding,
    File,
}

impl Which {
    /// Name as it is spelled out in diagnostics.
    fn label(self) -> &'static str {
        match self {
            Which::Horizontal => "--horizontal-scale <HSCALE>",
            Which::Vertical => "--vertical-scale <VSCALE>",
            Which::Padding => "--padding <PADDING>",
            Which::Encoding => "--encoding <ENCODING>",
            Which::File => "[FILE]",
        }
    }

    fn long(self) -> &'static str {
        match self {
            Which::Horizontal => "horizontal-scale",
            Which::Vertical => "vertical-scale",
            Which::Padding => "padding",
            Which::Encoding => "encoding",
            Which::File => "",
        }
    }

    fn choices(self) -> Option<&'static [&'static str]> {
        match self {
            Which::Encoding => Some(&["utf8-lossy", "utf8"]),
            _ => None,
        }
    }

    fn takes_value(self) -> bool {
        !matches!(self, Which::File)
    }
}

/// Option that takes a value, together with the spelling used on the command
/// line and a short flag when one exists.
const LONGS: [&str; 4] = ["horizontal-scale", "vertical-scale", "padding", "encoding"];

/// Long flags that do not take a value.
const FLAG_LONGS: [&str; 2] = ["version", "help"];

/// All long flags, in the order they appear in the help screen.
const ALL_LONGS: [&str; 6] = [
    "horizontal-scale",
    "vertical-scale",
    "padding",
    "encoding",
    "version",
    "help",
];

/// Usage shown when an argument has to be guessed.
const GUESSED: &str = "<FILE|--horizontal-scale <HSCALE>|--vertical-scale <VSCALE>|--padding <PADDING>|--encoding <ENCODING>|--version>";

/// One recognised occurrence on the command line.
enum Item {
    Option(Which, String),
    EmptyOption(Which),
    Positional(OsString),
    EmptyPositional,
    Duplicate(Which),
    Flag(Which),
    Subcommand(String, Vec<OsString>),
}

/// Everything that was found while scanning.
struct Scan {
    items: Vec<Item>,
    horizontal: Option<String>,
    vertical: Option<String>,
    padding: Option<String>,
    encoding: Option<String>,
    file: Option<OsString>,
    version: bool,
    help: bool,
}

impl Scan {
    fn new() -> Scan {
        Scan {
            items: Vec::new(),
            horizontal: None,
            vertical: None,
            padding: None,
            encoding: None,
            file: None,
            version: false,
            help: false,
        }
    }

    fn used(&self) -> bool {
        self.file.is_some()
            || self.horizontal.is_some()
            || self.vertical.is_some()
            || self.padding.is_some()
            || self.encoding.is_some()
    }
}

/// Similarity of two strings using the Jaro-Winkler score.
fn similarity(a: &str, b: &str) -> f64 {
    let left: Vec<char> = a.chars().collect();
    let right: Vec<char> = b.chars().collect();
    let (n, m) = (left.len(), right.len());
    if n == 0 || m == 0 {
        return 0.0;
    }
    let window = (std::cmp::max(n, m) / 2).saturating_sub(1);
    let mut seen_left = vec![false; n];
    let mut seen_right = vec![false; m];
    let mut hits = 0usize;
    for i in 0..n {
        let lo = i.saturating_sub(window);
        let hi = std::cmp::min(i + window + 1, m);
        for j in lo..hi {
            if !seen_right[j] && left[i] == right[j] {
                seen_left[i] = true;
                seen_right[j] = true;
                hits += 1;
                break;
            }
        }
    }
    if hits == 0 {
        return 0.0;
    }
    let mut transposed = 0usize;
    let mut cursor = 0usize;
    for i in 0..n {
        if !seen_left[i] {
            continue;
        }
        while !seen_right[cursor] {
            cursor += 1;
        }
        if left[i] != right[cursor] {
            transposed += 1;
        }
        cursor += 1;
    }
    let transposed = transposed / 2;
    let jaro = (hits as f64 / n as f64
        + hits as f64 / m as f64
        + (hits - transposed) as f64 / hits as f64)
        / 3.0;
    let mut prefix = 0usize;
    for i in 0..std::cmp::min(std::cmp::min(n, m), 4) {
        if left[i] == right[i] {
            prefix += 1;
        } else {
            break;
        }
    }
    jaro + prefix as f64 * 0.1 * (1.0 - jaro)
}

/// Closest of `choices` to `given`, if any is close enough.
fn closest(given: &str, choices: &[&str]) -> Option<String> {
    let mut best: Option<(f64, &str)> = None;
    for choice in choices {
        let score = similarity(given, choice);
        if score <= 0.7 {
            continue;
        }
        match best {
            Some((top, _)) if score <= top => {}
            _ => best = Some((score, choice)),
        }
    }
    best.map(|(_, name)| name.to_string())
}

/// Name of the binary as shown in usage lines.
fn bin_name(argv0: Option<&OsString>) -> String {
    match argv0 {
        Some(arg) => Path::new(arg)
            .file_name()
            .map(|name| name.to_string_lossy().into_owned())
            .unwrap_or_else(|| "code-minimap".to_string()),
        None => "code-minimap".to_string(),
    }
}

/// Read the whole command line and decide what to do.
pub fn parse(args: &[OsString]) -> Result<Outcome, Failure> {
    let bin = bin_name(args.first());
    let mut scan = Scan::new();
    let mut trailing = false;
    let mut index = 1;

    while index < args.len() {
        let raw = args[index].clone();
        let text = raw.to_string_lossy().into_owned();
        if !trailing && text == "--" {
            trailing = true;
            index += 1;
            continue;
        }
        if !trailing && text.starts_with("--") && text.len() > 2 {
            let body = &text[2..];
            let (name, inline) = match body.find('=') {
                Some(pos) => (&body[..pos], Some(body[pos + 1..].to_string())),
                None => (body, None),
            };
            let longs = LONGS.iter().map(|s| *s).collect::<Vec<&str>>();
            if let Some(pos) = LONGS.iter().position(|s| *s == name) {
                let which = match pos {
                    0 => Which::Horizontal,
                    1 => Which::Vertical,
                    2 => Which::Padding,
                    _ => Which::Encoding,
                };
                index += 1;
                scan_item(&mut scan, which, inline, args, &mut index, &bin)?;
                continue;
            }
            if FLAG_LONGS.contains(&name) {
                index += 1;
                match name {
                    "version" => scan.version = true,
                    _ => scan.help = true,
                }
                scan.items.push(Item::Flag(match name {
                    "version" => Which::Padding,
                    _ => Which::File,
                }));
                continue;
            }
            return Err(unexpected(&text, &bin, &scan));
        }
        if !trailing && text.starts_with('-') && text.len() > 1 {
            let chars: Vec<char> = text.chars().collect();
            let mut position = 1;
            let mut consumed = false;
            while position < chars.len() {
                let flag = chars[position];
                match flag {
                    'H' | 'V' => {
                        let which = if flag == 'H' {
                            Which::Horizontal
                        } else {
                            Which::Vertical
                        };
                        let rest: String = chars[position + 1..].iter().collect();
                        let attached = if rest.is_empty() {
                            None
                        } else {
                            Some(rest.trim_start_matches('=').to_string())
                        };
                        index += 1;
                        scan_item(&mut scan, which, attached, args, &mut index, &bin)?;
                        consumed = true;
                        break;
                    }
                    'h' => {
                        scan.help = true;
                        position += 1;
                    }
                    _ => {
                        let name = format!("-{}", flag);
                        return Err(unexpected(&name, &bin, &scan));
                    }
                }
            }
            if !consumed {
                index += 1;
            }
            continue;
        }
        if !trailing && (text == "completion" || text == "help") {
            let rest: Vec<OsString> = args[index + 1..].to_vec();
            scan.items.push(Item::Subcommand(text, rest));
            break;
        }
        if scan.file.is_some() {
            return Err(unexpected(&text, &bin, &scan));
        }
        if text.is_empty() {
            scan.items.push(Item::EmptyPositional);
        } else {
            scan.items.push(Item::Positional(raw.clone()));
        }
        scan.file = Some(raw);
        index += 1;
    }

    if let Some(Item::Subcommand(name, rest)) = scan.items.pop() {
        return subcommand(&name, &rest, &bin, &scan);
    }

    finish(&mut scan, &bin)
}

/// Record one option occurrence that takes a value.
fn scan_item(
    scan: &mut Scan,
    which: Which,
    inline: Option<String>,
    args: &[OsString],
    index: &mut usize,
    bin: &str,
) -> Result<(), Failure> {
    match inline {
        Some(value) => {
            if value.is_empty() {
                scan.items.push(Item::EmptyOption(which));
            } else {
                scan.items.push(Item::Option(which, value));
            }
            Ok(())
        }
        None => {
            if *index >= args.len() {
                return Err(missing_value(which));
            }
            let raw = args[*index].clone();
            let text = raw.to_string_lossy().into_owned();
            if text.starts_with('-') && text.len() > 1 {
                return Err(missing_value(which));
            }
            *index += 1;
            if text.is_empty() {
                scan.items.push(Item::EmptyOption(which));
            } else {
                scan.items.push(Item::Option(which, text));
            }
            Ok(())
        }
    }
}

/// Handle `completion` and `help`.
fn subcommand(
    name: &str,
    rest: &[OsString],
    bin: &str,
    scan: &Scan,
) -> Result<Outcome, Failure> {
    if name == "help" {
        return help(rest, bin);
    }
    let mut shell: Option<OsString> = None;
    let mut empty = false;
    let mut help = false;
    let mut trailing = false;
    let mut index = 0;
    while index < rest.len() {
        let raw = rest[index].clone();
        let text = raw.to_string_lossy().into_owned();
        if !trailing && text == "--" {
            trailing = true;
            index += 1;
            continue;
        }
        if !trailing && text.starts_with("--") && text.len() > 2 {
            let body = &text[2..];
            let (flag, inline) = match body.find('=') {
                Some(pos) => (&body[..pos], Some(body[pos + 1..].to_string())),
                None => (body, None),
            };
            if flag == "help" {
                if inline.is_some() {
                    return Err(unexpected(&text, bin, scan));
                }
                help = true;
                index += 1;
                continue;
            }
            return Err(unexpected(&text, bin, scan));
        }
        if !trailing && text.starts_with('-') && text.len() > 1 {
            let chars: Vec<char> = text.chars().collect();
            for flag in &chars[1..] {
                match flag {
                    'h' => help = true,
                    _ => {
                        let name = format!("-{}", flag);
                        return Err(unexpected(&name, bin, scan));
                    }
                }
            }
            index += 1;
            continue;
        }
        if shell.is_some() {
            return Err(unexpected(&text, bin, scan));
        }
        if text.is_empty() {
            empty = true;
        }
        shell = Some(raw);
        index += 1;
    }
    if help {
        return Ok(Outcome::Help(Screen::Completion));
    }
    let Some(value) = shell else {
        return Err(Failure::new(format!(
            "error: the following required arguments were not provided:\n  <SHELL>\n\nUsage: {} completion <SHELL>\n\nFor more information, try '--help'.\n",
            bin
        )));
    };
    let text = value.to_string_lossy().into_owned();
    if empty {
        return Err(Failure::new(
            "error: a value is required for '<SHELL>' but none was supplied\n\nFor more information, try '--help'.\n".to_string(),
        ));
    }
    match Shell::from_name(&text) {
        Some(shell) => Ok(Outcome::Completion(shell)),
        None => {
            let names = Shell::names();
            let list = names.join(", ");
            let hint = closest(&text, &names)
                .map(|name| format!("\n\n  tip: a similar value exists: '{}'", name))
                .unwrap_or_default();
            Err(Failure::new(format!(
                "error: invalid value '{}' for '<SHELL>'\n  [possible values: {}]{}\n\nFor more information, try '--help'.\n",
                text, list, hint
            )))
        }
    }
}

/// Handle the `help` subcommand, which prints another screen.
fn help(rest: &[OsString], bin: &str) -> Result<Outcome, Failure> {
    let mut screen = Screen::Main;
    let mut usage = format!("{} [OPTIONS] [FILE] [COMMAND]", bin);
    for raw in rest {
        let name = raw.to_string_lossy().into_owned();
        match (name.as_str(), &screen) {
            ("completion", Screen::Main) => {
                screen = Screen::Completion;
                usage = format!("{} completion <SHELL>", bin);
            }
            ("help", Screen::Main) => {
                screen = Screen::Help;
                usage = format!("{} help [COMMAND]...", bin);
            }
            _ => {
                return Err(Failure::new(format!(
                    "error: unrecognized subcommand '{}'\n\nUsage: {}\n\nFor more information, try '--help'.\n",
                    name, usage
                )))
            }
        }
    }
    Ok(Outcome::Help(screen))
}

/// Convert the collected values and detect repeated options.
fn finish(scan: &mut Scan, bin: &str) -> Result<Outcome, Failure> {
    // Repeated options are noticed only once every value has been accepted.
    let duplicates: Vec<Which> = scan
        .items
        .iter()
        .filter_map(|item| match item {
            Item::Duplicate(which) => Some(*which),
            _ => None,
        })
        .collect();
    for item in scan.items.clone() {
        match item {
            Item::Option(which, value) => {
                check_value(which, &value, bin)?;
            }
            Item::EmptyOption(which) => {
                if which.choices().is_some() {
                    return Err(missing_value(which));
                }
                check_value(which, "", bin)?;
            }
            Item::EmptyPositional => {
                return Err(Failure::new(
                    "error: a value is required for '[FILE]' but none was supplied\n\nFor more information, try '--help'.\n".to_string(),
                ));
            }
            _ => {}
        }
    }
    if let Some(which) = duplicates.first() {
        return Err(Failure::new(format!(
            "error: the argument '{}' cannot be used multiple times\n\nUsage: {} [OPTIONS] [FILE] [COMMAND]\n\nFor more information, try '--help'.\n",
            which.label(),
            bin
        )));
    }
    if scan.help {
        return Ok(Outcome::Help(Screen::Main));
    }
    if scan.version {
        return Ok(Outcome::Version);
    }
    Ok(Outcome::Render {
        file: scan.file.clone(),
        options: Options {
            horizontal_scale: scan
                .horizontal
                .as_ref()
                .and_then(|value| value.parse().ok())
                .unwrap_or(1.0),
            vertical_scale: scan
                .vertical
                .as_ref()
                .and_then(|value| value.parse().ok())
                .unwrap_or(1.0),
            padding: scan.padding.as_ref().and_then(|value| value.parse().ok()),
        },
        encoding: scan
            .encoding
            .as_ref()
            .and_then(|value| Encoding::from_name(value))
            .unwrap_or(Encoding::Utf8Lossy),
    })
}

/// Make sure a value can be understood.
fn check_value(which: Which, value: &str, _bin: &str) -> Result<(), Failure> {
    match which {
        Which::Horizontal | Which::Vertical => match value.parse::<f64>() {
            Ok(_) => Ok(()),
            Err(err) => Err(bad_value(value, which.label(), &err.to_string())),
        },
        Which::Padding => match value.parse::<usize>() {
            Ok(_) => Ok(()),
            Err(err) => Err(bad_value(value, which.label(), &err.to_string())),
        },
        Which::Encoding => {
            if Encoding::from_name(value).is_some() {
                return Ok(());
            }
            let choices = which.choices().unwrap_or(&[]);
            let list = choices.join(", ");
            let hint = closest(value, choices)
                .map(|name| format!("\n\n  tip: a similar value exists: '{}'", name))
                .unwrap_or_default();
            Err(Failure::new(format!(
                "error: invalid value '{}' for '{}'\n  [possible values: {}]{}\n\nFor more information, try '--help'.\n",
                value, which.label(), list, hint
            )))
        }
        Which::File => Ok(()),
    }
}

fn bad_value(value: &str, label: &str, reason: &str) -> Failure {
    Failure::new(format!(
        "error: invalid value '{}' for '{}': {}\n\nFor more information, try '--help'.\n",
        value, label, reason
    ))
}

fn missing_value(which: Which) -> Failure {
    let extra = match which.choices() {
        Some(choices) => format!("\n  [possible values: {}]", choices.join(", ")),
        None => String::new(),
    };
    Failure::new(format!(
        "error: a value is required for '{}' but none was supplied{}\n\nFor more information, try '--help'.\n",
        which.label(),
        extra
    ))
}

/// Diagnostic for an argument that is not part of the interface.
fn unexpected(text: &str, bin: &str, scan: &Scan) -> Failure {
    let stripped = text.trim_start_matches('-');
    if !stripped.is_empty() {
        if let Some(name) = closest(stripped, &ALL_LONGS) {
            let suggestion = format!("--{}", name);
            let usage = if name == "help" {
                if scan.used() {
                    format!("{} --help {}", bin, GUESSED)
                } else {
                    format!("{} --help [FILE]", bin)
                }
            } else {
                format!("{} {}", bin, GUESSED)
            };
            return Failure::new(format!(
                "error: unexpected argument '{}' found\n\n  tip: a similar argument exists: '{}'\n\nUsage: {}\n\nFor more information, try '--help'.\n",
                text, suggestion, usage
            ));
        }
    }
    let tip = if text.starts_with('-') {
        format!("\n\n  tip: to pass '{}' as a value, use '-- {}'", text, text)
    } else {
        String::new()
    };
    Failure::new(format!(
        "error: unexpected argument '{}' found{}\n\nUsage: {} [OPTIONS] [FILE] [COMMAND]\n\nFor more information, try '--help'.\n",
        text, tip, bin
    ))
}

/// Same diagnostic, but for the completion subcommand.
fn unexpected_in_completion(text: &str, bin: &str, help: bool) -> Failure {
    if help {
        return Failure::new(format!(
            "error: unexpected argument '{}' found\n\n  tip: a similar argument exists: '--help'\n\nUsage: {} completion --help <SHELL>\n\nFor more information, try '--help'.\n",
            text, bin
        ));
    }
    let tip = if text.starts_with('-') {
        format!("\n\n  tip: to pass '{}' as a value, use '-- {}'", text, text)
    } else {
        String::new()
    };
    Failure::new(format!(
        "error: unexpected argument '{}' found{}\n\nUsage: {} completion <SHELL>\n\nFor more information, try '--help'.\n",
        text, tip, bin
    ))
}

/// Text of a help screen.
pub fn help_text(bin: &str, screen: &Screen) -> String {
    match screen {
        Screen::Main | Screen::Help => format!(
            "A high performance code minimap generator\n\nUsage: {} [OPTIONS] [FILE] [COMMAND]\n\nCommands:\n  completion\n          Generate shell completion file\n  help\n          Print this message or the help of the given subcommand(s)\n\nArguments:\n  [FILE]\n          File to read\n\nOptions:\n  -H, --horizontal-scale <HSCALE>\n          Specify horizontal scale factor [default: 1.0]\n  -V, --vertical-scale <VSCALE>\n          Specify vertical scale factor [default: 1.0]\n      --padding <PADDING>\n          Specify padding width\n      --encoding <ENCODING>\n          Specify input encoding [default: utf8-lossy] [possible values: utf8-lossy, utf8]\n      --version\n          Print version\n  -h, --help\n          Print help\n",
            bin
        ),
        Screen::Completion => format!(
            "Generate shell completion file\n\nUsage: {} completion <SHELL>\n\nArguments:\n  <SHELL>\n          Target shell name [possible values: bash, elvish, fish, powershell, zsh]\n\nOptions:\n  -h, --help\n          Print help\n",
            bin
        ),
    }
}
