    }
}

/// The option a diagnostic talks about.
#[derive(Clone, Copy, PartialEq, Eq)]
enum Which {
    Horizontal,
    Vertical,
    Padding,
    Encoding,
    File,
}

impl Which {
    /// Name as spelled out in diagnostics.
    fn label(self) -> &'static str {
        match self {
            Which::Horizontal => "--horizontal-scale <HSCALE>",
            Which::Vertical => "--vertical-scale <VSCALE>",
            Which::Padding => "--padding <PADDING>",
            Which::Encoding => "--encoding <ENCODING>",
            Which::File => "[FILE]",
        }
    }

    fn choices(self) -> Option<&'static [&'static str]> {
        match self {
            Which::Encoding => Some(&["utf8-lossy", "utf8"]),
            _ => None,
        }
    }
}

/// Long flags that carry a value.
const VALUE_LONGS: [&str; 4] = ["horizontal-scale", "vertical-scale", "padding", "encoding"];

/// Long flags that do not carry a value.
const FLAG_LONGS: [&str; 2] = ["version", "help"];

/// Every long flag, in the order of the help screen.
const ALL_LONGS: [&str; 6] = [
    "horizontal-scale",
    "vertical-scale",
    "padding",
    "encoding",
    "version",
    "help",
];

/// Usage shown when an argument has to be guessed.
const GUESSED: &str = "<FILE|--horizontal-scale <HSCALE>|--vertical-scale <VSCALE>|--padding <PADDING>|--encoding <ENCODING>|--version>";

/// One recognised occurrence on the command line.
enum Item {
    Value(Which, String),
    Empty(Which),
    Duplicate(Which),
    Positional(OsString),
    EmptyPositional,
    Version,
    Help,
}

/// Everything found while scanning the command line.
#[derive(Default)]
struct Scan {
    items: Vec<Item>,
    file: Option<OsString>,
    seen: [bool; 4],
    used: bool,
}

impl Scan {
    /// Mark an option as used and remember a repetition.
    fn record(&mut self, which: usize) -> bool {
        if self.seen[which] {
            return true;
        }
        self.seen[which] = true;
        self.used = true;
        false
    }
}

/// Similarity of two strings using the Jaro-Winkler score.
fn similarity(a: &str, b: &str) -> f64 {
    let left: Vec<char> = a.chars().collect();
    let right: Vec<char> = b.chars().collect();
    let (n, m) = (left.len(), right.len());
    if n == 0 || m == 0 {
        return 0.0;
    }
    let window = (std::cmp::max(n, m) / 2).saturating_sub(1);
    let mut seen_left = vec![false; n];
    let mut seen_right = vec![false; m];
    let mut hits = 0usize;
    for i in 0..n {
        let lo = i.saturating_sub(window);
        let hi = std::cmp::min(i + window + 1, m);
        for j in lo..hi {
            if !seen_right[j] && left[i] == right[j] {
                seen_left[i] = true;
                seen_right[j] = true;
                hits += 1;
                break;
            }
        }
    }
    if hits == 0 {
        return 0.0;
    }
    let mut transposed = 0usize;
    let mut cursor = 0usize;
    for i in 0..n {
        if !seen_left[i] {
            continue;
        }
        while !seen_right[cursor] {
            cursor += 1;
        }
        if left[i] != right[cursor] {
            transposed += 1;
        }
        cursor += 1;
    }
    let transposed = transposed / 2;
    let jaro = (hits as f64 / n as f64
        + hits as f64 / m as f64
        + (hits - transposed) as f64 / hits as f64)
        / 3.0;
    let mut prefix = 0usize;
    for i in 0..std::cmp::min(std::cmp::min(n, m), 4) {
        if left[i] == right[i] {
            prefix += 1;
        } else {
            break;
        }
    }
    jaro + prefix as f64 * 0.1 * (1.0 - jaro)
}

/// Closest of `choices` to `given`, if any is close enough.
fn closest(given: &str, choices: &[&str]) -> Option<String> {
    let mut best: Option<(f64, &str)> = None;
    for choice in choices {
        let score = similarity(given, choice);
        if score <= 0.7 {
            continue;
        }
        match best {
            Some((top, _)) if score <= top => {}
            _ => best = Some((score, choice)),
        }
    }
    best.map(|(_, name)| name.to_string())
}

/// Name of the binary as shown in usage lines.
fn bin_name(argv0: Option<&OsString>) -> String {
    match argv0 {
        Some(arg) => Path::new(arg)
            .file_name()
            .map(|name| name.to_string_lossy().into_owned())
            .unwrap_or_else(|| "code-minimap".to_string()),
        None => "code-minimap".to_string(),
    }
}

/// Read the command line and decide what to do.
pub fn parse(args: &[OsString]) -> Result<Outcome, Failure> {
    let bin = bin_name(args.first());
    let mut scan = Scan::default();
    let mut trailing = false;
    let mut index = 1;

    while index < args.len() {
        let raw = args[index].clone();
        let text = raw.to_string_lossy().into_owned();
        if !trailing && text == "--" {
            trailing = true;
            index += 1;
            continue;
        }
        if !trailing && text.starts_with("--") && text.len() > 2 {
            let body = &text[2..];
            let (name, inline) = match body.find('=') {
                Some(pos) => (&body[..pos], Some(body[pos + 1..].to_string())),
                None => (body, None),
            };
            if let Some(slot) = VALUE_LONGS.iter().position(|s| *s == name) {
                index += 1;
                let which = match slot {
                    0 => Which::Horizontal,
                    1 => Which::Vertical,
                    2 => Which::Padding,
                    _ => Which::Encoding,
                };
                take_value(&mut scan, which, inline, args, &mut index, &bin)?;
                continue;
            }
            match name {
                "version" => {
                    index += 1;
                    scan.items.push(Item::Version);
                    continue;
                }
                "help" => {
                    index += 1;
                    scan.items.push(Item::Help);
                    continue;
                }
                _ => return Err(unexpected(&text, &bin, &scan)),
            }
        }
        if !trailing && text.starts_with('-') && text.len() > 1 {
            let chars: Vec<char> = text.chars().collect();
            let mut position = 1;
            let mut consumed = false;
            while position < chars.len() {
                match chars[position] {
                    'H' | 'V' => {
                        let which = if chars[position] == 'H' {
                            Which::Horizontal
                        } else {
                            Which::Vertical
                        };
                        let rest: String = chars[position + 1..].iter().collect();
                        let attached = if rest.is_empty() {
                            None
                        } else {
                            Some(rest.strip_prefix('=').unwrap_or(&rest).to_string())
                        };
                        index += 1;
                        take_value(&mut scan, which, attached, args, &mut index, &bin)?;
                        consumed = true;
                        break;
                    }
                    'h' => {
                        position += 1;
                        scan.items.push(Item::Help);
                    }
                    _ => {
                        let name = format!("-{}", chars[position]);
                        return Err(unexpected(&name, &bin, &scan));
                    }
                }
            }
            if !consumed {
                index += 1;
            }
            continue;
        }
        if !trailing && (text == "completion" || text == "help") {
            let rest: Vec<OsString> = args[index + 1..].to_vec();
            return dispatch(&text, &rest, &bin, &mut scan);
        }
        if scan.file.is_some() {
            return Err(unexpected(&text, &bin, &scan));
        }
        if text.is_empty() {
            scan.items.push(Item::EmptyPositional);
        } else {
            scan.items.push(Item::Positional(raw.clone()));
        }
        scan.file = Some(raw);
        scan.used = true;
        index += 1;
    }

    review(&mut scan, &bin)
}

/// Attach a value to an option, either inline or from the next argument.
fn take_value(
    scan: &mut Scan,
    which: usize_kind,
    inline: Option<String>,
    args: &[OsString],
    index: &mut usize,
    bin: &str,
) -> Result<(), Failure>
where
    usize_kind = usize,
{
    unreachable!()
}

type usize_kind = usize;

fn attach_value(
    scan: &mut Scan,
    slot: usize,
    inline: Option<String>,
    args: &[OsString],
    index: &mut usize,
    bin: &str,
) -> Result<(), Failure> {
    let which = match slot {
        0 => Which::Horizontal,
        1 => Which::Vertical,
        2 => Which::Padding,
        _ => Which::Encoding,
    };
    match inline {
        Some(value) => {
            remember(scan, slot, which, value);
            Ok(())
        }
        None => {
            if *index >= args.len() {
                return Err(missing_value(which));
            }
            let raw = args[*index].clone();
            let text = raw.to_string_lossy().into_owned();
            if text.starts_with('-') && text.len() > 1 {
                return Err(missing_value(which));
            }
            *index += 1;
            remember(scan, slot, which, text);
            Ok(())
        }
    }
}

fn remember(scan: &mut Scan, slot: usize, which: Which, value: String) {
    if scan.record(slot) {
        scan.items.push(Item::Duplicate(which));
        return;
    }
    scan.used = true;
    if value.is_empty() {
        scan.items.push(Item::Empty(which));
    } else {
        scan.items.push(Item::Value(which, value));
    }
}

/// Handle `completion` and `help`.
fn dispatch(
    name: &str,
    rest: &[OsString],
    bin: &str,
    scan: &mut Scan,
) -> Result<Outcome, Failure> {
    if name == "help" {
        return help_screen(rest, bin);
    }
    let mut shell: Option<OsString> = None;
    let mut empty = false;
    let mut help = false;
    let mut trailing = false;
    let mut index = 0;
    while index < rest.len() {
        let raw = rest[index].clone();
        let text = raw.to_string_lossy().into_owned();
        if !trailing && text == "--" {
            trailing = true;
            index += 1;
            continue;
        }
        if !trailing && text.starts_with("--") && text.len() > 2 {
            let body = &text[2..];
            let (flag, inline) = match body.find('=') {
                Some(pos) => (&body[..pos], Some(body[pos + 1..].to_string())),
                None => (body, None),
            };
            if flag == "help" && inline.is_none() {
                help = true;
                index += 1;
                continue;
            }
            return Err(unexpected_in_completion(&text, bin, help));
        }
        if !trailing && text.starts_with('-') && text.len() > 1 {
            let chars: Vec<char> = text.chars().collect();
            for flag in &chars[1..] {
                match flag {
                    'h' => help = true,
                    _ => {
                        let name = format!("-{}", flag);
                        return Err(unexpected_in_completion(&name, bin, help));
                    }
                }
            }
            index += 1;
            continue;
        }
        if shell.is_some() {
            return Err(unexpected_in_completion(&text, bin, help));
        }
        if text.is_empty() {
            empty = true;
        }
        shell = Some(raw);
        index += 1;
    }
    if help {
        return Ok(Outcome::Help(Screen::Completion));
    }
    let Some(value) = shell else {
        return Err(Failure::new(format!(
            "error: the following required arguments were not provided:\n  <SHELL>\n\nUsage: {} completion <SHELL>\n\nFor more information, try '--help'.\n",
            bin
        )));
    };
    let text = value.to_string_lossy().into_owned();
    if empty {
        return Err(Failure::new(
            "error: a value is required for '<SHELL>' but none was supplied\n\nFor more information, try '--help'.\n".to_string(),
        ));
    }
    let shell = match Shell::from_name(&text) {
        Some(shell) => shell,
        None => {
            let names = Shell::names();
            let list = names.join(", ");
            let hint = closest(&text, &names)
                .map(|name| format!("\n\n  tip: a similar value exists: '{}'", name))
                .unwrap_or_default();
            return Err(Failure::new(format!(
                "error: invalid value '{}' for '<SHELL>'\n  [possible values: {}]{}\n\nFor more information, try '--help'.\n",
                text, list, hint
            )));
        }
    };
    // Values of the outer command are still checked before anything runs.
    review(scan, bin)?;
    Ok(Outcome::Completion(shell))
}

/// Handle `help`, which prints another screen.
fn help_screen(rest: &[OsString], bin: &str) -> Result<Outcome, Failure> {
    let mut screen = Screen::Main;
    let mut usage = format!("{} [OPTIONS] [FILE] [COMMAND]", bin);
    for raw in rest {
        let name = raw.to_string_lossy().into_owned();
        match (name.as_str(), &screen) {
            ("completion", Screen::Main) => {
                screen = Screen::Completion;
                usage = format!("{} completion <SHELL>", bin);
            }
            ("help", Screen::Main) => {
                screen = Screen::Help;
                usage = format!("{} help [COMMAND]...", bin);
            }
            _ => {
                return Err(Failure::new(format!(
                    "error: unrecognized subcommand '{}'\n\nUsage: {}\n\nFor more information, try '--help'.\n",
                    name, usage
                )))
            }
        }
    }
    Ok(Outcome::Help(screen))
}

/// Walk the collected items, converting values and spotting repetitions.
fn review(scan: &mut Scan, bin: &str) -> Result<Outcome, Failure> {
    for item in scan.items.clone() {
        match item {
            Item::Value(which, value) => check_value(which, &value)?,
            Item::Empty(which) => {
                if which.choices().is_some() {
                    return Err(missing_value(which));
                }
                check_value(which, "")?;
            }
            Item::EmptyPositional => {
                return Err(Failure::new(
                    "error: a value is required for '[FILE]' but none was supplied\n\nFor more information, try '--help'.\n".to_string(),
                ));
            }
            Item::Duplicate(which) => {
                return Err(Failure::new(format!(
                    "error: the argument '{}' cannot be used multiple times\n\nUsage: {} [OPTIONS] [FILE] [COMMAND]\n\nFor more information, try '--help'.\n",
                    which.label(),
                    bin
                )));
            }
            Item::Help => return Ok(Outcome::Help(Screen::Main)),
            Item::Version => return Ok(Outcome::Version),
            Item::Positional(_) => {}
        }
    }
    Ok(Outcome::Render {
        file: scan.file.clone(),
        options: Options {
            horizontal_scale: 1.0,
            vertical_scale: 1.0,
            padding: None,
        },
        encoding: Encoding::Utf8Lossy,
    })
}

/// Make sure a value can be understood.
fn check_value(which: Which, value: &str) -> Result<(), Failure> {
    match which {
        Which::Horizontal | Which::Vertical => match value.parse::<f64>() {
            Ok(_) => Ok(()),
            Err(err) => Err(bad_value(value, which.label(), &err.to_string())),
        },
        Which::Padding => match value.parse::<usize>() {
            Ok(_) => Ok(()),
            Err(err) => Err(bad_value(value, which.label(), &err.to_string())),
        },
        Which::Encoding => {
            if Encoding::from_name(value).is_some() {
                return Ok(());
            }
            let choices = which.choices().unwrap_or(&[]);
            let list = choices.join(", ");
            let hint = closest(value, choices)
                .map(|name| format!("\n\n  tip: a similar value exists: '{}'", name))
                .unwrap_or_default();
            Err(Failure::new(format!(
                "error: invalid value '{}' for '{}'\n  [possible values: {}]{}\n\nFor more information, try '--help'.\n",
                value, which.label(), list, hint
            )))
        }
        Which::File => Ok(()),
    }
}

fn bad_value(value: &str, label: &str, reason: &str) -> Failure {
    Failure::new(format!(
        "error: invalid value '{}' for '{}': {}\n\nFor more information, try '--help'.\n",
        value, label, reason
    ))
}

fn missing_value(which: Which) -> Failure {
    let extra = match which.choices() {
        Some(choices) => format!("\n  [possible values: {}]", choices.join(", ")),
        None => String::new(),
    };
    Failure::new(format!(
        "error: a value is required for '{}' but none was supplied{}\n\nFor more information, try '--help'.\n",
        which.label(),
        extra
    ))
}

/// Diagnostic for an argument outside of the interface.
fn unexpected(text: &str, bin: &str, scan: &Scan) -> Failure {
    let stripped = text.trim_start_matches('-');
    if !stripped.is_empty() {
        if let Some(name) = closest(stripped, &ALL_LONGS) {
            let suggestion = format!("--{}", name);
            let usage = if name == "help" && scan.used {
                format!("{} --help {}", bin, GUESSED)
            } else if name == "help" {
                format!("{} --help [FILE]", bin)
            } else {
                format!("{} {}", bin, GUESSED)
            };
            return Failure::new(format!(
                "error: unexpected argument '{}' found\n\n  tip: a similar argument exists: '{}'\n\nUsage: {}\n\nFor more information, try '--help'.\n",
                text, suggestion, usage
            ));
        }
    }
    let tip = if text.starts_with('-') {
        format!("\n\n  tip: to pass '{}' as a value, use '-- {}'", text, text)
    } else {
        String::new()
    };
    Failure::new(format!(
        "error: unexpected argument '{}' found{}\n\nUsage: {} [OPTIONS] [FILE] [COMMAND]\n\nFor more information, try '--help'.\n",
        text, tip, bin
    ))
}

/// Same diagnostic for the completion subcommand.
fn unexpected_in_completion(text: &str, bin: &str, help: bool) -> Failure {
    if help {
        return Failure::new(format!(
            "error: unexpected argument '{}' found\n\n  tip: a similar argument exists: '--help'\n\nUsage: {} completion --help <SHELL>\n\nFor more information, try '--help'.\n",
            text, bin
        ));
    }
    let tip = if text.starts_with('-') {
        format!("\n\n  tip: to pass '{}' as a value, use '-- {}'", text, text)
    } else {
        String::new()
    };
    Failure::new(format!(
        "error: unexpected argument '{}' found{}\n\nUsage: {} completion <SHELL>\n\nFor more information, try '--help'.\n",
        text, tip, bin
    ))
}

/// Text of a help screen.
pub fn help_text(bin: &str, screen: &Screen) -> String {
    match screen {
        Screen::Main => format!(
            "A high performance code minimap generator\n\nUsage: {} [OPTIONS] [FILE] [COMMAND]\n\nCommands:\n  completion\n          Generate shell completion file\n  help\n          Print this message or the help of the given subcommand(s)\n\nArguments:\n  [FILE]\n          File to read\n\nOptions:\n  -H, --horizontal-scale <HSCALE>\n          Specify horizontal scale factor [default: 1.0]\n  -V, --vertical-scale <VSCALE>\n          Specify vertical scale factor [default: 1.0]\n      --padding <PADDING>\n          Specify padding width\n      --encoding <ENCODING>\n          Specify input encoding [default: utf8-lossy] [possible values: utf8-lossy, utf8]\n      --version\n          Print version\n  -h, --help\n          Print help\n",
            bin
        ),
        Screen::Completion => format!(
            "Generate shell completion file\n\nUsage: {} completion <SHELL>\n\nArguments:\n  <SHELL>\n          Target shell name [possible values: bash, elvish, fish, powershell, zsh]\n\nOptions:\n  -h, --help\n          Print help\n",
            bin
        ),
        Screen::Help => format!(
            "Print this message or the help of the given subcommand(s)\n\nUsage: {} help [COMMAND]...\n\nArguments:\n  [COMMAND]...\n          Print help for the subcommand(s)\n",
            bin
        ),
    }
}
