            Encoding::Utf8 => "utf8",
        }
    }

    fn from_name(name: &str) -> Option<Encoding> {
        match name {
            "utf8-lossy" => Some(Encoding::Utf8Lossy),
            "utf8" => Some(Encoding::Utf8),
            _ => None,
        }
    }
}
